"""Generate a C header containing the rule baseline thresholds."""

from __future__ import annotations

import argparse
import json
import re
from pathlib import Path


def macro_name(name: str) -> str:
    return "EGO_SC_" + re.sub(r"[^A-Z0-9]+", "_", name.upper()).strip("_")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("config")
    parser.add_argument("output")
    args = parser.parse_args()
    config = json.loads(Path(args.config).read_text(encoding="utf-8"))
    lines = [
        "/* Auto-generated by generate_c_header.py. Do not edit manually. */",
        "#ifndef EGO_SAFETY_ROUTER_THRESHOLDS_H",
        "#define EGO_SAFETY_ROUTER_THRESHOLDS_H",
        "",
        f'#define EGO_SC_MODEL_VERSION "{config["model_version"]}"',
        "",
    ]
    for section in ("thresholds", "weights", "defaults"):
        lines.append(f"/* {section} */")
        for key, value in sorted(config[section].items()):
            suffix = "f" if isinstance(value, float) else ""
            lines.append(f"#define {macro_name(section + '_' + key)} ({value}{suffix})")
        lines.append("")
    lines.extend(["#endif /* EGO_SAFETY_ROUTER_THRESHOLDS_H */", ""])
    output = Path(args.output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text("\n".join(lines), encoding="utf-8", newline="\n")
    print(f"Generated {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
